class Solution {
public:
    vector<int> avoidFlood(vector<int>& rains) {
        unordered_map<int, vector<int>> lookup;
        for (int i = rains.size() - 1; i >= 0; --i) {
            lookup[rains[i]].emplace_back(i);
        }
        vector<int> result;
        priority_queue<int, vector<int>, greater<int>> min_heap;
        for (int i = 0; i < rains.size(); ++i) {
            if (rains[i]) {
                if (lookup[rains[i]].size() >= 2) {
                    lookup[rains[i]].pop_back();
                    min_heap.emplace(lookup[rains[i]].back());
                }
                result.emplace_back(-1);
            } else if (!min_heap.empty()) {
                int j = min_heap.top(); min_heap.pop();
                if (j < i) {
                    return {};
                }
                result.emplace_back(rains[j]);
            } else {
                result.emplace_back(1);
            }
        }
        return min_heap.empty() ? result : vector<int>();
    }
};

import collections
import heapq


class Solution(object):
    def avoidFlood(self, rains):
        """
        :type rains: List[int]
        :rtype: List[int]
        """
        lookup = collections.defaultdict(list)
        i = len(rains)-1
        for lake in reversed(rains):
            lookup[lake].append(i)
            i -= 1
        result, min_heap = [], []
        for i, lake in enumerate(rains):
            if lake:
                if len(lookup[lake]) >= 2:
                    lookup[lake].pop()
                    heapq.heappush(min_heap, lookup[lake][-1])
                result.append(-1)
            elif min_heap:
                j = heapq.heappop(min_heap)
                if j < i:
                    return []
                result.append(rains[j])
            else:
                result.append(1)
        return result if not min_heap else []

